// TypeScript port of the revolve-groove group's translators: docs/spikes/solidcraft-referee/contract/revolve-groove-rig/rg-translate-p4.mjs (the phase 7 pane translator translate-p4.mjs with
// eleven asserted patches, generated by make-translators.mjs) and rg-translate-p0.mjs (the same patches on phase0/translate.mjs), with revolve-groove.guard.mjs (revolve-groove-guard.ts).
// Behaviour-preserving: same guards in the same order, same sentences, same command lists, same engine calls (the one addition is the time limit below).
//
// THE LAYER'S BASE IS THE PHASE 4 TRANSLATOR, WHICH IS WHAT rg-translate-p4.mjs PATCHES. So this set equals the p4 original on EVERY document (no exclusion set), and the p0 original on every document in which
// phase0 and phase 4 plan every other feature the same way (NOTES.md "Fold 6"). The set is
//     base (phase 4) planners  +  the guarded revolve / groove planners (G1, G3, G4, G7, G8, G9, G10: revolve-groove-guard.ts guardPlan)  +  the group's loop (rgStep)
// where the group's loop differs from the generic loop in exactly the patches of make-translators.mjs:
//   * aggregate (G2): a cut that splits a body returns 'name (1)': every piece counts (aggregateRG), and the surface area is summed;
//   * a built groove that left the part unchanged is refused (G5, postCheck);
//   * the engine's refusal of a spin / groove becomes one plain sentence (G6, plainRefusal); every other kind keeps the base wording;
//   * a refused groove leaves its target handle pointing at itself (the chain, RG-CHAIN), so a later feature on the same part is refused with a pointer instead of building on the un-grooved part;
//   * the accepted commands are exposed to the guard (st.accepted; G10 reads them);
//   * the note of a feature carries the original's `guard` object (the cost features and the engine angle) as `rg`. The layer's `guard` is the CODE of the guard that refused (new: the original has none).
//
// TIME. The group's rule for the page (revolve-groove.guard.mjs, COST_BUDGET_S): the page runs every groove in a Worker and stops it at 45 s. The original translator has no code for it. As in the holes,
// patterns-mirror and booleans folds, the layer asks the host: ctx.runSC(cmds, { budgetS }) with budgetS = 45 + 1.5 x the CPU the last run used, on every run of a groove, and refuses a { ok: false, timedOut: true }
// reply with a plain sentence (guard G-BUDGET). THIS IS ADVICE: a host whose runSC ignores the option leaves the run unbounded.
//
// The group is NOT accepted in Phase 1 (LAYER-CONTRACT.md, "revolve-groove: unresolved"). The known holes are in this port on purpose: see NOTES.md, Fold 6.
//
// No kernel is named: everything that touches an engine comes in through the context object. Non-null assertions (!) stand for fields the feature's kind guarantees on a well-formed doc; the original
// reads them unguarded, so a malformed doc throws the same TypeError, which the step turns into the same translator-error refusal.
import type { Feature } from '@shuff57/reshape-script/model-types';
import type { RunResult } from './types.js';
import { BASE_PROFILE, planFeature, refuse, resolveNamesFor, membersOf } from './translate.js';
import { SKETCH_VOLUME_GUARD, sketchVolumeRefusal } from './sketch-volume.js';
import { POCKET_CUT_GUARD, pocketCutRefusal, rememberRun } from './pocket-cut.js';
import { OPEN_OUTLINE_GUARD } from './open-outline.js';
import type { Aggregate, FeatureResult, LoopEnv, Plan, PlanCtx, Planner, Profile, TranslateState } from './translate.js';
import { COST_BUDGET_S, guardPlan, onRefused, plainRefusal, plainRefusalCode, postCheck, rgView } from './revolve-groove-guard.js';
import type { RGPlan, RGRefusal } from './revolve-groove-guard.js';

export * as revolveGrooveGuard from './revolve-groove-guard.js';

/** The kinds this set owns. */
export const RG_KINDS = ['revolve', 'groove'];
/**
 * The guards of this set that look at features of kinds it does not own: the chain (a later feature on a part whose groove was refused is refused with a pointer instead of being built on the un-grooved part).
 * Its time limit applies to the runs of a groove only; G4, G7 .. G10 decide a groove from the measure of its target, whichever step built that.
 */
export const RG_CROSS_KIND_GUARDS = ['RG-CHAIN'];
export const RG_BUDGET_S = COST_BUDGET_S;

/** The group's bookkeeping beside the generic state. */
export interface RGState {
  /** the grooves that were refused and so re-pointed their target's handle at themselves (the chain), by id */
  chained: Record<string, true>;
  /** CPU seconds the last run used, when the host reports it: the budget of the next groove run is 45 + 1.5 x this */
  lastRunS: number;
}

/** A groove or a spin built from the bodies the engine reports: the loose piece match of G2 ('name' and 'name (k)') and the summed surface area. */
export function aggregateRG(res: RunResult, names: string[]): Aggregate | null {
  const bs = res.measure!.bodies.filter((b) => names.some((n) => b.name === n || b.name.startsWith(`${n} (`))); // G2: a cut that splits a body returns 'name (1)'
  if (!bs.length) return null;
  const lo = [Infinity, Infinity, Infinity]; const hi = [-Infinity, -Infinity, -Infinity];
  for (const b of bs) for (let i = 0; i < 3; i++) { lo[i] = Math.min(lo[i], b.bbox.min[i]); hi[i] = Math.max(hi[i], b.bbox.max[i]); }
  return {
    volume: bs.reduce((s, b) => s + b.volume_mm3, 0),
    faces: bs.reduce((s, b) => s + b.faces, 0),
    kernelFaces: bs.reduce((s, b) => s + b.kernel.faces, 0),
    curved: bs.some((b) => Object.keys(b.face_types ?? {}).some((k) => k !== 'plane')),
    bbox: [...lo, ...hi],
    area: bs.reduce((a, b) => a + (b.area_mm2 ?? 0), 0),
    faceTypes: bs.reduce((a: Record<string, number>, b) => { for (const [k, v] of Object.entries(b.face_types ?? {})) a[k] = (a[k] ?? 0) + v; return a; }, {}),
    com: [0, 1, 2].map((i) => bs.reduce((a, b) => a + b.volume_mm3 * b.center_of_mass[i], 0) / bs.reduce((a, b) => a + b.volume_mm3, 0)),
    bodies: bs.map((b) => b.name),
  };
}

/** The sentence for a groove the engine did not finish within the time limit. One sentence, no engine word. */
export const rgBudgetSentence = (id: string): string => `${id} (groove): this groove took longer than ${COST_BUDGET_S} seconds to calculate, so it was stopped and the part is shown without it; use a ring with straight sides, or a part without round walls.`;

// ---- the planner ---------------------------------------------------------------------------------------------------------------------------------
/** The guarded planner of a revolve / groove: the guard, then the base planner of that kind (the original's guardPlan(planFeatureRaw)). */
const rgPlanner: Planner = (f, st, ctx) => guardPlan((g, s, c) => planFeature(g, s, c, BASE_PROFILE), f, st, ctx);
/** What the step plans with: the base planners, and this group's guarded revolve and groove. The dependency, outline and planner-error wording is the base's. */
const RG_PLAN: Profile = { ...BASE_PROFILE, name: 'revolve-groove(plan)', planners: { revolve: rgPlanner, groove: rgPlanner } };

const DEP_REFUSED = /^\S+ \(\w+\): its \w+ (\S+) was refused \(/;

// ---- the loop ------------------------------------------------------------------------------------------------------------------------------------
export async function rgStep(f: Feature, idx: number, env: LoopEnv): Promise<void> {
  const { doc, ctx, st, accepted, out, shapeCache } = env;
  const rs = st.rg!;
  st.accepted = accepted; // G10: the guard reads the commands already accepted
  const prefix = doc.features.slice(0, idx);
  const resolved = await resolveNamesFor(f, prefix, { st, accepted, ctx, shapeCache });
  const fctx: PlanCtx = { ...ctx, resolve: (name) => resolved.get(name) ?? null };
  const note = (o: Omit<FeatureResult, 'id' | 'kind'>): void => { out.push({ id: f.id, kind: f.kind, ...o }); };
  if (f.kind === 'sketch') st.sketches[f.id] = f;
  let plan: Plan;
  try { plan = planFeature(f, st, fctx, RG_PLAN); } catch (e) { plan = refuse(`${f.id} (${f.kind}): translator error: ${(e as Error).message}`); }
  const own = f.kind === 'revolve' || f.kind === 'groove';
  if ('refusal' in plan) {
    st.refused[f.id] = plan.refusal;
    if (onRefused(rgView(f), st)) rs.chained[f.id] = true;
    const pr = plan as RGRefusal;
    let code: string | undefined = pr.code ?? (pr.guard === OPEN_OUTLINE_GUARD ? pr.guard : undefined);
    if (!code && !own) { const m = DEP_REFUSED.exec(plan.refusal); if (m && rs.chained[m[1]]) code = 'RG-CHAIN'; } // a later feature on a part whose groove was refused
    note({ status: 'refused', refusal: plan.refusal, commands: [], ...(code ? { guard: code } : {}), ...(pr.rg ? { rg: pr.rg } : {}) });
    return;
  }
  if ('noop' in plan) { note({ status: 'noop', commands: [] }); return; }
  const rg = (plan as RGPlan).rg;
  let lastErr: string | { plain: string } | null = null;
  let lastFail: RunResult | null = null;
  let timedOut = false;
  for (const variant of plan.variants) {
    let res: RunResult;
    // time: a groove's engine runs carry { budgetS } (advice to the host, see the header); every other run is as in the original (no option)
    try { res = f.kind === 'groove' ? await ctx.runSC([...accepted, ...variant], { budgetS: RG_BUDGET_S + 1.5 * rs.lastRunS }) : await ctx.runSC([...accepted, ...variant]); } catch (e) { res = { ok: false, failed: { error: `bridge error: ${(e as Error).message}` } }; }
    if (!res.ok) {
      if (res.timedOut && f.kind === 'groove') { timedOut = true; lastErr = res.failed ? `${res.failed.command}: ${res.failed.error}` : 'TIME BUDGET: the run did not finish'; lastFail = res; continue; }
      lastErr = res.failed ? `${res.failed.command}: ${res.failed.error}` : String(res.rejected ?? res.error ?? 'unknown'); lastFail = res; continue;
    }
    const m = aggregateRG(res, plan.produces);
    if (!m) { lastErr = `solidcraft ran the commands but no body named ${plan.produces.join(', ')} came back`; continue; }
    // every set: the built pull against its sketch (sketch-volume.ts)
    const sv = f.kind === 'extrude' ? sketchVolumeRefusal(f, st.sketches[f.target], ctx, res, plan.produces) : null;
    if (sv) { st.refused[f.id] = sv; if (onRefused(rgView(f), st)) rs.chained[f.id] = true; note({ status: 'refused', refusal: sv, guard: SKETCH_VOLUME_GUARD, commands: variant }); return; }
    { const post = postCheck(f, st, m, new Set(ctx.guardsOff ?? [])); if (post) { lastErr = post; continue; } } // G5
    // the sets with no after-the-build check of a pocket: the cut against the tool that made it (pocket-cut.ts, the extrude-pocket group's check and sentence)
    const pc = f.kind === 'pocket' ? await pocketCutRefusal(f, ctx, res, accepted, variant, plan.produces, ctx.runSC) : null;
    if (pc) { st.refused[f.id] = pc; if (onRefused(rgView(f), st)) rs.chained[f.id] = true; note({ status: 'refused', refusal: pc, guard: POCKET_CUT_GUARD, commands: variant }); return; }
    accepted.push(...variant);
    rememberRun(accepted, res);
    for (const mp of membersOf(env.profile)) mp.onAccepted?.(st, res, m, plan, { f, ctx });
    st.accLen[f.id] = accepted.length;
    st.bodies[f.id] = m.bodies;
    st.measure[f.id] = m;
    for (const c of plan.consumes) {
      if (c === f.id) continue;
      if (f.kind === 'hole' || f.kind === 'pocket' || f.kind === 'groove') { if (c === (f.kind === 'hole' ? (f as unknown as { target: string }).target : (f as unknown as { into: string }).into)) st.head[c] = f.id; } else st.stale[c] = f.id;
    }
    note({ status: 'built', commands: variant, measure: m, ...(rg ? { rg } : {}), pickedFrom: plan.pickedFrom, evidence: plan.evidence ?? null, pick: (variant.find((c) => c.params.edges || c.params.faces)?.params) ?? null, variantsTried: plan.variants.indexOf(variant) + 1 });
    return;
  }
  let sentence: string; let code: string | undefined;
  if (timedOut) { sentence = rgBudgetSentence(f.id); code = 'G-BUDGET'; }
  else {
    const plain = plainRefusal(f, lastErr);
    sentence = plain ?? `${f.id} (${f.kind}): solidcraft refused it -- ${lastErr as string | null}`; // G6
    if (plain !== null) code = plainRefusalCode(f, lastErr);
  }
  st.refused[f.id] = sentence;
  if (onRefused(rgView(f), st)) rs.chained[f.id] = true;
  note({ status: 'refused', refusal: sentence, commands: plan.variants[0], ...(code ? { guard: code } : {}), ...(rg ? { rg } : {}), failed: lastFail?.failed ?? null, sketchAtFailure: lastFail?.sketch_at_failure ?? null });
}

export const RG_PROFILE: Profile = {
  name: 'revolve-groove',
  // claiming revolve and groove is what makes this profile their owner in a composition; the real planning is rgPlanner, called by the step through RG_PLAN
  planners: { revolve: rgPlanner, groove: rgPlanner },
  verifies: false,
  initState(st: TranslateState) { st.rg = { chained: {}, lastRunS: 0 }; },
  depSentence: BASE_PROFILE.depSentence,
  noOutline: BASE_PROFILE.noOutline,
  plannerError: BASE_PROFILE.plannerError,
  kernelRefusal: BASE_PROFILE.kernelRefusal,
  // how long the last accepted run took, whichever step built it: the budget of the next groove run is 45 s + 1.5 x this
  onAccepted(st, res) { if (res.cpuMs) st.rg!.lastRunS = res.cpuMs / 1000; },
  step: rgStep,
};
